function renderDealWinners(){const target=$('deal-winner-list'),status=$('deal-winner-status');if(!target||!status)return;target.replaceChildren();const vehicles=read().filter(item=>item.category==='Vehicles'||!!liveSavedVehicle(item));const results=vehicles.map(dealWinnerScore),ranked=results.filter(r=>r.score!==null).sort((a,b)=>b.score-a.score||b.profit-a.profit||a.item.title.localeCompare(b.item.title));status.textContent=ranked.length+' ranked of '+vehicles.length+' saved vehicles • '+(vehicles.length-ranked.length)+' unranked for missing data';if(!vehicles.length){target.append(el('p','Save vehicle auctions to see a ranked shortlist.','small muted'));return}for(const [i,r] of ranked.entries()){const card=el('article',undefined,'deal-winner-card');card.append(el('h4',(i===0?'🏆 ':'#'+(i+1)+' ')+(r.vehicle?.title||r.item.title)),el('p','Deal Winner '+r.score+'/100 • Expected profit '+money(r.profit)+' • Bid headroom '+money(r.headroom),'small'));const details=el('details');details.append(el('summary','How this score was calculated'));for(const [label,points,max,why] of r.parts)details.append(el('p',label+': '+points+'/'+max+' • '+why,'small'));details.append(el('p','Score weights: profit 35, risk 30, headroom 20, evidence 15. Profit is capped at $3,000 for scoring, not forecasting. Rankings are heuristics, not probability of success.','small muted'));card.append(details);if(r.warnings.length)card.append(el('p','⚠ '+r.warnings.join(' • '),'small muted'));const button=el('button','Open research workspace','button secondary');button.type='button';button.addEventListener('click',()=>showNativeAuction(r.vehicle));card.append(button);target.append(card)}for(const r of results.filter(v=>v.score===null)){const card=el('article',undefined,'deal-winner-card');card.append(el('h4','Unranked: '+r.item.title),el('p',r.reason,'small muted'));target.append(card)}}
function renderComparison(){const target=$('comparison-table'),status=$('comparison-status');if(!target||!status)return;target.replaceChildren();const saved=read(),selection=comparisonSelection().filter(url=>saved.some(v=>v.url===url));if(selection.length!==comparisonSelection().length)localStorage.setItem(COMPARE_KEY,JSON.stringify(selection));const items=selection.map(url=>comparisonData(saved.find(v=>v.url===url)));status.textContent=items.length+' of 4 vehicles selected • Swipe the comparison sideways on iPhone.';if(!items.length){target.append(el('p','Select Compare on two to four saved vehicles to view them side by side.','small muted'));return}const table=el('table',undefined,'comparison-grid'),thead=el('thead'),head=el('tr');head.append(el('th','Metric'));for(const {item,vehicle} of items){const th=el('th'),name=el('strong',vehicle?.title||item.title),remove=el('button','✕','button secondary compare-remove');remove.type='button';remove.setAttribute('aria-label','Remove '+item.title+' from comparison');remove.addEventListener('click',()=>toggleComparison(item.url));th.append(name,remove);if(vehicle){const open=el('button','Research ↗','button secondary compare-open');open.type='button';open.addEventListener('click',()=>showNativeAuction(vehicle));th.append(open)}head.append(th)}thead.append(head);table.append(thead);const body=el('tbody');for(const key of ['Current reported bid','Estimated resale','Expected net profit','Expected max bid','Risk score','Auction freshness','Sold comparison confidence']){const row=el('tr');row.append(el('th',key));for(const {values} of items)row.append(el('td',values[key]??'Unavailable'));body.append(row)}table.append(body);target.append(table);$('comparison-clear').disabled=!items.length}
function savedProfit(item){const vehicle=liveSavedVehicle(item);if(vehicle)return getResale(vehicle.id)?.profit??null;return upside(item)}
function render(){renderVehicles();renderTopDeals();const all=read(),filter=$('filter-text').value.trim().toLowerCase(),cat=$('filter-category').value,status=$('filter-status').value;let rows=all.filter(x=>(!filter||[x.title,x.notes,x.url].some(v=>String(v||'').toLowerCase().includes(filter)))&&(!cat||x.category===cat)&&(!status||x.status===status));if($('sort').value==='profit')rows.sort((a,b)=>(savedProfit(b)??-Infinity)-(savedProfit(a)??-Infinity));else if($('sort').value==='title')rows.sort((a,b)=>a.title.localeCompare(b.title));else rows.sort((a,b)=>b.created-a.created);$('metric-total').textContent=all.length;$('metric-watch').textContent=all.filter(x=>x.status==='Watching').length;const calculated=all.map(savedProfit).filter(v=>v!==null);$('metric-profit').textContent=calculated.length?money(calculated.reduce((a,b)=>a+b,0)):'N/A';$('result-count').textContent=rows.length+' of '+all.length+' saved listings';const target=$('listings');target.replaceChildren();if(!rows.length)target.append(el('p','No matching listings yet. Save a vehicle from the carousel or add an auction link.','muted'));for(const x of rows){const vehicle=liveSavedVehicle(x),isGsa=x.url.startsWith('https://www.gsaauctions.gov/'),card=el('article',undefined,'listing watchlist-card'),head=el('div',undefined,'listing-head'),title=el('h3',vehicle?.title||x.title),pill=el('span',x.status,'pill');head.append(title,pill);card.append(head);if(vehicle?.image&&(/^\.\/auction-images\/[a-f0-9]{20}\.jpg$/.test(vehicle.image)||/^https:\/\/(?:webassets\.lqdt1\.com\/assets\/photos\/|files\.lqdt1\.com\/photos\/)/.test(vehicle.image))){const img=document.createElement('img');img.src=vehicle.image;img.alt='Auction photo for '+vehicle.title;img.loading='lazy';img.className='watchlist-photo';card.append(img)}else if(isGsa||x.source?.startsWith('GovDeals'))card.append(el('div','Photo unavailable in the current feed','watchlist-photo-missing'));const bid=vehicle?vehicle.price:x.bid;const details=el('div',undefined,'watchlist-facts');const history=readBidHistory()[x.url];if(vehicle&&history?.previous!==null&&history?.previous!==undefined&&history.previous!==history.current)card.append(el('p','📈 Bid changed: '+money(history.previous)+' → '+money(history.current),'watchlist-alert'));const freshness=vehicle?auctionFreshness(vehicle):null;if(freshness&&freshness.status!=='current')card.append(el('p',freshness.label,'watchlist-alert'));const warning=closingWarning(vehicle);if(warning)card.append(el('p',warning,'watchlist-alert'));details.append(el('span','Current reported bid: '+(bid===null||bid===undefined?'Not reported':money(bid))));details.append(el('span','Ends: '+(vehicle?.ends||'Check auction')));details.append(el('span',vehicle?vehicle.city+', '+vehicle.state:isGsa?'Not in current feed':x.category));if((isGsa||x.source?.startsWith('GovDeals'))&&!vehicle)details.append(el('span','Live listing not found in current feed; saved details may be stale'));card.append(details);if(vehicle)card.append(riskScoreElement(vehicle));if(!isGsa)card.append(el('p',x.notes||'Manually saved auction','small muted'));const actions=el('div',undefined,'watchlist-actions'),link=el('a','View auction ↗','button secondary');link.href=x.url;link.target='_blank';link.rel='noopener noreferrer';actions.append(link);if(vehicle){const estimate=getResale(vehicle.id),profit=el('button',estimate?'★ '+money(estimate.profit)+' est.':'★ No comp','button watchlist-profit');profit.type='button';profit.setAttribute('aria-label','Resale Analysis for '+vehicle.title);profit.addEventListener('click',()=>openResale(vehicle));actions.append(auctionDetailButton(vehicle),profit,bidButton(vehicle))}else if(isGsa||x.source?.startsWith('GovDeals'))actions.append(el('span','★ Analysis unavailable until listing appears in current feed','small muted'));else if(upside(x)!==null)actions.append(el('span','Estimated upside: '+money(upside(x)),'small muted'));if(vehicle){const compare=el('button',comparisonSelection().includes(x.url)?'✓ Comparing':'⚖ Compare','button secondary');compare.type='button';compare.setAttribute('aria-pressed',String(comparisonSelection().includes(x.url)));compare.addEventListener('click',()=>{toggleComparison(x.url);render()});actions.append(compare)}const remove=el('button','🗑 Remove','button danger');remove.type='button';remove.setAttribute('aria-label','Remove '+x.title+' from saved listings');remove.addEventListener('click',()=>{if(confirm('Remove this saved auction?')){save(read().filter(v=>v.url!==x.url));render()}});actions.append(remove);card.append(actions);target.append(card)}renderComparison();renderDealWinners();renderWatchdog()}
function updateEstimate(){const a=num('bid'),b=num('fees'),c=num('resale');$('estimate').textContent=a!==null&&c!==null?'Estimated upside: '+money(c-a-(b??0))+' (not guaranteed; excludes unentered costs)':'Enter estimated purchase and resale values to calculate upside.'}
function submit(e){e.preventDefault();const url=safeUrl($('auction').value);if(!url){$('auction').setCustomValidity('Enter an official HTTPS GovDeals URL');$('auction').reportValidity();return}$('auction').setCustomValidity('');const all=read();if(all.some(v=>v.url===url)){$('feedback').textContent='This auction is already saved.';return}const bid=num('bid'),fees=num('fees'),resale=num('resale');if([bid,fees,resale].some(v=>v!==null&&(!Number.isFinite(v)||v<0||v>100000000))){$('feedback').textContent='Enter valid nonnegative amounts.';return}const lat=num('vehicle-lat'),lon=num('vehicle-lon');if((lat===null)!==(lon===null)||lat!==null&&(lat< -90||lat>90||lon< -180||lon>180)){$('feedback').textContent='Enter both valid listing latitude and longitude, or leave both blank.';return}const item={lat,lon,id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),url,title:$('title').value.trim(),category:CATS.includes($('category').value)?$('category').value:'Other',status:STATES.includes($('status').value)?$('status').value:'Watching',bid,fees,resale,notes:$('notes').value.trim(),created:Date.now()};if(!item.title){$('feedback').textContent='A listing title is required.';return}try{all.unshift(item);save(all)}catch{$('feedback').textContent='Unable to save. Browser storage may be disabled or full.';return}$('listing-form').reset();$('feedback').textContent='Saved successfully.';updateEstimate();nav('saved')}
async function copy(text){try{await navigator.clipboard.writeText(text);return true}catch{return false}}
let viewerLocation=null,vehicleIndex=0,liveVehicles=[],govVehicles=[],feedHealth={gov:null,gsa:null,sold:null,licensed:null},feedStatus='Loading current GSA Auctions listings…',feedTime=null;
function distanceMiles(a,b,c,d){const rad=x=>x*Math.PI/180,R=3958.7613,dl=rad(c-a),dn=rad(d-b),h=Math.sin(dl/2)**2+Math.cos(rad(a))*Math.cos(rad(c))*Math.sin(dn/2)**2;return 2*R*Math.asin(Math.min(1,Math.sqrt(h)))}
function endingTime(x){const raw=String(x.ends||'');const d=Date.parse(raw);return Number.isFinite(d)?d:Infinity}
function auctionFreshness(x,now=Date.now()){const isGov=x.source?.startsWith('GovDeals');const observed=Date.parse(x.observed_at||'');const ending=endingTime(x);if(Number.isFinite(ending)&&ending<now)return {status:'ended',label:'⚠️ Reported auction end passed'};if(isGov){if(!Number.isFinite(observed))return {status:'unknown',label:'⚠️ Third-party listing age unknown • verify on GovDeals'};const hours=(now-observed)/3600000;if(hours>24)return {status:'stale',label:'⚠️ Third-party listing last observed '+Math.floor(hours)+'h ago • verify on GovDeals'};return {status:'unverified',label:'⚠️ Third-party observed '+Math.max(0,Math.floor(hours))+'h ago • official status unverified'}}const observedGsa=Date.parse(feedHealth.gsa?.fetched_at||'');if(Number.isFinite(observedGsa)&&(now-observedGsa)>12*3600000)return {status:'stale',label:'⚠️ GSA feed over 12 hours old'};return {status:'current',label:'GSA feed recently updated • check auction before bidding'}}
function auctionRank(x){const profit=getResale(x.id);return profit&&Number.isFinite(profit.profit)?profit.profit:-Infinity}
function nearbyVehicles(){const radius=$('vehicle-radius').value,sort=$('vehicle-sort')?.value||'closing';return [...govVehicles,...liveVehicles].filter(x=>radius==='all'||viewerLocation&&Number.isFinite(x.lat)&&Number.isFinite(x.lon)&&distanceMiles(viewerLocation.lat,viewerLocation.lon,x.lat,x.lon)<=Number(radius)).sort((a,b)=>{const fa=auctionFreshness(a).status,fb=auctionFreshness(b).status;const bad=x=>['ended','stale'].includes(x)?1:0;const penalty=bad(fa)-bad(fb);if(penalty)return penalty;if(sort==='profit')return (Number.isFinite(auctionRank(b))?auctionRank(b):-1e15)-(Number.isFinite(auctionRank(a))?auctionRank(a):-1e15)||(Number.isFinite(endingTime(a))?endingTime(a):1e15)-(Number.isFinite(endingTime(b))?endingTime(b):1e15);if(sort==='source')return (a.source.startsWith('GovDeals')?0:1)-(b.source.startsWith('GovDeals')?0:1)||endingTime(a)-endingTime(b);return (Number.isFinite(endingTime(a))?endingTime(a):1e15)-(Number.isFinite(endingTime(b))?endingTime(b):1e15)||(a.source.startsWith('GovDeals')?0:1)-(b.source.startsWith('GovDeals')?0:1)||a.title.localeCompare(b.title)})}
async function loadLiveVehicles(){try{const r=await fetch('./govdeals-vehicles.json',{cache:'no-store'});if(r.ok){const d=await r.json();feedHealth.gov=d;govVehicles=Array.isArray(d.listings)?d.listings.filter(x=>typeof x.title==='string'&&/^https:\/\/www\.govdeals\.com\/asset\/\d+\/\d+$/.test(x.url)):[]}}catch{}try{const res=await fetch('./gsa-vehicles.json',{cache:'no-store'});if(!res.ok)throw Error('Feed unavailable');const payload=await res.json();if(!Array.isArray(payload.listings))throw Error('Invalid feed');liveVehicles=payload.listings.filter(x=>typeof x.title==='string'&&typeof x.url==='string'&&x.url.startsWith('https://www.gsaauctions.gov/')&&Number.isFinite(x.lat)&&Number.isFinite(x.lon));feedHealth.gsa=payload;feedTime=payload.fetched_at;const ageHours=(Date.now()-Date.parse(feedTime))/3600000;feedStatus='GovDeals: '+govVehicles.length+' listings • GSA: '+liveVehicles.length+' national listings • Updated '+new Date(feedTime).toLocaleString()+(ageHours>12?' • Data may be stale':'');}catch{feedStatus='Live auction feed is temporarily unavailable. Try again later.'}recordBidChanges();render();loadServerWatchdog();if(watchdogAnalysisReady)captureWatchdog();renderFeedHealth();renderTopDeals()}
const AUTO_DEST_KEY='blakeypoo.destinationZip.v1';let zipCoords=null,verifiedSold=[];
function extractVehicleIdentity(title){const match=String(title||'').match(/\b(19\d{2}|20\d{2})\s+(Ford|Chevrolet|Chevy|Dodge|Jeep|Toyota|Honda|Nissan|Hyundai|Kia|GMC|Ram|Buick|Chrysler)\s+([A-Za-z0-9-]+)/i);return match?{year:Number(match[1]),make:match[2].toLowerCase().replace('chevy','chevrolet'),model:match[3].toLowerCase().replace(/[^a-z0-9]/g,'')}:null}
function comparableSales(x){const v=extractVehicleIdentity(x.title);if(!v)return {matches:[],confidence:'none',yearGap:null};const matches=verifiedSold.map(c=>({sale:c,id:extractVehicleIdentity(c.title)})).filter(c=>c.id&&c.id.make===v.make&&c.id.model===v.model&&Math.abs(c.id.year-v.year)<=2&&Number.isFinite(c.sale.price)&&c.sale.price>=0&&c.sale.sold_date).sort((a,b)=>Math.abs(a.id.year-v.year)-Math.abs(b.id.year-v.year)||b.sale.sold_date.localeCompare(a.sale.sold_date));if(!matches.length)return {matches:[],confidence:'none',yearGap:null};const bestGap=Math.abs(matches[0].id.year-v.year);const selected=matches.filter(c=>Math.abs(c.id.year-v.year)===bestGap).slice(0,5).map(c=>c.sale);const confidence=bestGap===0?(selected.length>=3?'moderate':'limited'):'low';return {matches:selected,confidence,yearGap:bestGap}}
function matchingSold(x){return comparableSales(x).matches}
function median(values){const a=[...values].sort((x,y)=>x-y);return a.length?a.length%2?a[(a.length-1)/2]:(a[a.length/2-1]+a[a.length/2])/2:null}
function estimatedTransport(x,zip){const a=zipCoords&&zipCoords[zip];if(!a||!Number.isFinite(x.lat)||!Number.isFinite(x.lon))return null;const direct=distanceMiles(x.lat,x.lon,a[0],a[1]);const roadMiles=Math.ceil(direct*1.25);return {direct,roadMiles,cost:Math.round((300+roadMiles*1.5)/25)*25,formula:'Illustrative assumption: $300 base + $1.50 per estimated road mile (1.25× straight-line). Not a carrier quote.'}}
async function loadAnalysisSources(){try{const r=await fetch('./licensed-feed-status.json',{cache:'no-store'});if(r.ok)feedHealth.licensed=await r.json()}catch{}try{const r=await fetch('./us-zip-coordinates.json',{cache:'force-cache'});if(r.ok)zipCoords=await r.json()}catch{}try{const r=await fetch('./verified-sold-comps.json',{cache:'no-store'});if(r.ok){const data=await r.json();feedHealth.sold=data;verifiedSold=Array.isArray(data.listings)?data.listings.filter(c=>c&&typeof c.title==='string'&&Number.isFinite(c.price)&&/^https:\/\//.test(c.url)&&/^\d{4}-\d{2}-\d{2}$/.test(c.sold_date)&&c.verified===true):[]}}catch{}}
const RESALE_KEY='blakeypoo.resale.v1';let activeResale=null;
function readResale(){try{const v=JSON.parse(localStorage.getItem(RESALE_KEY)||'{}');return v&&typeof v==='object'&&!Array.isArray(v)?v:{}}catch{return {}}}
function resaleCalc(v){const keys=['cost','shipping','premium','other','value'];if(!v||!keys.every(k=>Number.isFinite(v[k])&&v[k]>=0)||v.premium>100)return null;const buyerPremium=v.cost*v.premium/100;const total=v.cost+buyerPremium+v.shipping+v.other;return {buyerPremium,total,profit:v.value-total}}
function autoResale(x){if(!Number.isFinite(x.price)||x.price<0)return null;const comps=matchingSold(x);if(!comps.length)return null;const value=median(comps.map(c=>c.price));const saved=readResale()[x.id]||{};const dest=localStorage.getItem(AUTO_DEST_KEY)||'';const transport=estimatedTransport(x,dest);const shipping=transport?transport.cost:675;const v={cost:x.price,shipping,premium:0,other:0,value};const result=resaleCalc(v);return result?{...result,...v,comps,confidence:comparableSales(x).confidence,yearGap:comparableSales(x).yearGap,shippingAssumption:!transport,otherExcluded:true}:null}
function profitScenarios(x){const base={...autoResale(x),...readResale()[x.id]};if(!Number.isFinite(base.value)||!Number.isFinite(base.cost))return null;const quality=comparableSales(x),gov=x.source?.startsWith('GovDeals');const transport=Number.isFinite(base.shipping)?base.shipping:675;const user=readResale()[x.id];const feeRate=user&&Number.isFinite(user.premium)?user.premium:(gov?12.5:0);const taxRate=0.07;const cost=base.cost;const risk=/\b(as.is|non.running|does not run|salvage|engine issue|transmission issue|wreck|damage|parts only)\b/i.test(x.title)?'high':'unknown';const repair=risk==='high'?1800:650;const values=[['Conservative',0.75,1.35,2,1.6],['Expected',1,1,1,1],['Optimistic',1.12,0.85,0.45,0.55]];const scenarios=values.map(([name,valueFactor,shippingFactor,repairFactor,taxFactor])=>{const resale=base.value*valueFactor,shipping=transport*shippingFactor,repairs=repair*repairFactor,tax=cost*taxRate*taxFactor,fees=cost*feeRate/100,other=user&&Number.isFinite(user.other)?user.other:0,total=cost+fees+shipping+repairs+tax+other;return {name,profit:Math.round(resale-total),resale:Math.round(resale),shipping:Math.round(shipping),repairs:Math.round(repairs),tax:Math.round(tax),fees:Math.round(fees),total:Math.round(total)}});return {scenarios,confidence:quality.confidence,comps:quality.matches.length,feeRate,taxRate,risk,transport,source:gov?'GovDeals':'GSA',feeVerified:!!(user&&Number.isFinite(user.premium)),taxAssumption:'Illustrative 7% purchase-tax allowance; actual tax depends on jurisdiction, exemption and transaction',repairAssumption:risk==='high'?'Higher repair reserve due to title wording':'Unknown condition: $650 expected repair reserve; no inspection',shippingAssumption:'Transport is illustrative, not a carrier quote',saleAssumption:'Auction sold comps are not guaranteed resale prices'}}
function getResale(id){const saved=resaleCalc(readResale()[id]);if(saved)return saved;const x=[...govVehicles,...liveVehicles].find(x=>x.id===id);return x?autoResale(x):null}
function openResale(x){activeResale=x;$('resale-vehicle').textContent=x.title+' • '+x.city+', '+x.state;const v=readResale()[x.id]||autoResale(x)||{};$('resale-destination').value=localStorage.getItem(AUTO_DEST_KEY)||'';populateAutomaticResale(x,v);for(const [key,id] of [['cost','resale-cost'],['shipping','resale-shipping'],['premium','resale-premium'],['other','resale-other'],['value','resale-value']])$(id).value=v[key]??(key==='cost'&&Number.isFinite(x.price)?x.price:'');updateResaleBreakdown();$('resale-dialog').showModal()}
function populateAutomaticResale(x,saved){const comps=matchingSold(x),target=$('resale-comps');target.replaceChildren();const med=median(comps.map(c=>c.price));if(comps.length){target.append(el('p','Completed auction matches: '+comps.length+' • Median sold price: '+money(med)+' • Confidence: '+comparableSales(x).confidence,'small'));for(const c of comps){const a=el('a',c.title+' • Sold '+c.sold_date+' • '+money(c.price)+' ↗','small');a.href=c.url;a.target='_blank';a.rel='noopener noreferrer';target.append(a);if(c.notes)target.append(el('p','Condition note: '+c.notes,'small muted'))}if(saved.value===undefined)$('resale-value').value=med}else target.append(el('p','No verified recently sold match is available for this exact year/make/model. Automatic profit cannot be shown.','small muted'));const transport=estimatedTransport(x,$('resale-destination').value.trim());if(transport&&saved.shipping===undefined)$('resale-shipping').value=transport.cost;const quality=comparableSales(x);const premiumNote=(x.source?.startsWith('GovDeals')?'Buyer premium: 0% placeholder ONLY; GovDeals buyer fees vary by lot and must be entered before trusting any profit figure. ':'GSA Auctions general buyer premium: 0% assumption (check lot-specific terms). ')+ 'Other taxes/repairs not included unless entered. '+(quality.yearGap>0?'Nearby-model-year comparison (±2 years), low confidence. ':'')+'Confidence: '+quality.confidence+'. '; $('resale-auto-status').textContent=premiumNote+' Top Deals scenarios reserve 7% illustrative purchase tax, transport, and condition-dependent repairs. GovDeals 12.5% premium is an unverified planning allowance, NOT a quoted fee. '+(transport?'Transport estimate: '+money(transport.cost)+' for ~'+transport.roadMiles+' road miles. '+transport.formula:'Without a destination ZIP, automatic estimates use $675 transport (250-mile illustrative trip). Enter ZIP to improve the estimate.')+(comps.length?' Verified sold comparables linked below.':' No verified sold comparable data available.');updateResaleBreakdown()}
function updateResaleBreakdown(){const v={};for(const [key,id] of [['cost','resale-cost'],['shipping','resale-shipping'],['premium','resale-premium'],['other','resale-other'],['value','resale-value']]){const raw=$(id).value.trim();v[key]=raw===''?NaN:Number(raw)}const result=resaleCalc(v);$('resale-breakdown').textContent=result?'Purchase: '+money(v.cost)+' • Buyer premium ('+v.premium+'%): '+money(result.buyerPremium)+' • Transport: '+money(v.shipping)+' • Other: '+money(v.other)+' • Total cost: '+money(result.total)+' • Resale estimate: '+money(v.value)+' • Potential profit: '+money(result.profit):'Complete all fields, including verified buyer premium and estimated resale value, to calculate potential profit.';return {v,result}}
function saveResale(e){e.preventDefault();if(!activeResale)return;const {v,result}=updateResaleBreakdown();if(!result)return;const all=readResale();if(/^\d{5}$/.test($('resale-destination').value.trim()))localStorage.setItem(AUTO_DEST_KEY,$('resale-destination').value.trim());all[activeResale.id]=v;localStorage.setItem(RESALE_KEY,JSON.stringify(all));$('resale-dialog').close();renderVehicles();renderTopDeals()}
const BID_PLAN_KEY='blakeypoo.bidplan.v1';let activeBidVehicle=null;
function readBidPlans(){try{return JSON.parse(localStorage.getItem(BID_PLAN_KEY)||'{}')||{}}catch{return {}}}
function bidCeiling(resale,target,premiumPercent,taxPercent,transport,repairs,other=0){const vals=[resale,target,premiumPercent,taxPercent,transport,repairs,other];if(!vals.every(Number.isFinite)||vals.some(x=>x<0)||premiumPercent>100||taxPercent>100)return null;return Math.max(0,Math.floor((resale-target-transport-repairs-other)/(1+(premiumPercent+taxPercent)/100)))}
function bidPlanDefaults(x){const sc=profitScenarios(x);if(!sc)return null;const saved=readBidPlans()[x.id]||{};return {target:500,premium:sc.feeRate,tax:7,transport:sc.transport,repairs:sc.risk==='high'?1800:650,other:0,resale:sc.scenarios[1].resale,...saved}}
function bidPlanScenarios(x,plan){if(!plan)return null;const rows=[['Conservative',.75,1.35,2,1.6],['Expected',1,1,1,1],['Optimistic',1.12,.85,.45,.55]];return rows.map(([name,resaleFactor,shippingFactor,repairFactor,taxFactor])=>({name,ceiling:bidCeiling(plan.resale*resaleFactor,plan.target,plan.premium,plan.tax*taxFactor,plan.transport*shippingFactor,plan.repairs*repairFactor,plan.other)}))}
function showBidPlan(x){activeBidVehicle=x;const plan=bidPlanDefaults(x);if(!plan)return;$('bid-vehicle').textContent=x.title;for(const key of ['target','premium','tax','transport','repairs','other','resale'])$('bid-'+key).value=plan[key];$('bid-preview').max=String(Math.max(25000,Math.ceil((Number(x.price)||0)*2/100)*100));$('bid-preview').value=Math.max(0,Number(x.price)||0);updateBidPlan();$('bid-dialog').showModal()}
function bidProfitAt(plan,bid,scenario){const factors={Conservative:[.75,1.35,2,1.6],Expected:[1,1,1,1],Optimistic:[1.12,.85,.45,.55]}[scenario];if(!factors||![plan.resale,plan.premium,plan.tax,plan.transport,plan.repairs,plan.other,bid].every(Number.isFinite))return null;return plan.resale*factors[0]-bid*(1+(plan.premium+plan.tax*factors[3])/100)-plan.transport*factors[1]-plan.repairs*factors[2]-plan.other}
function bidBreakEven(plan,scenario){const adjusted={...plan,target:0};return bidPlanScenarios(activeBidVehicle,adjusted)?.find(x=>x.name===scenario)?.ceiling??null}
function renderBidChart(plan,rows){const host=$('bid-chart');host.replaceChildren();const warnings=$('bid-warnings');warnings.replaceChildren();const bid=Number($('bid-preview').value),range=Math.max(1000,...rows.map(r=>r.ceiling*1.25),bid*1.15);$('bid-preview').max=String(Math.ceil(range/100)*100);const width=720,height=300,left=66,right=18,top=20,bottom=44,plotW=width-left-right,plotH=height-top-bottom;const names=['Conservative','Expected','Optimistic'],colors=['#e7a77c','#7bb9ff','#84d6a0'];const samples=names.flatMap(n=>[0,range].map(x=>bidProfitAt(plan,x,n)));const low=Math.min(0,plan.target,...samples),high=Math.max(0,plan.target,...samples);const ymin=low-Math.max(100,(high-low)*.08),ymax=high+Math.max(100,(high-low)*.08);const sx=x=>left+x/range*plotW,sy=y=>top+(ymax-y)/(ymax-ymin)*plotH;const ns='http://www.w3.org/2000/svg';const svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.setAttribute('role','img');svg.setAttribute('aria-label','Bid versus profit chart: three scenario lines, target profit and break-even markers');svg.classList.add('bid-chart-svg');function node(tag,attrs={},label){const e=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,String(v));if(label!==undefined)e.textContent=label;svg.append(e);return e}for(let i=0;i<=4;i++){const y=ymin+(ymax-ymin)*i/4;node('line',{x1:left,y1:sy(y),x2:width-right,y2:sy(y),stroke:'#536577','stroke-width':.7});node('text',{x:4,y:sy(y)+4,fill:'#d8e1ec','font-size':12},money(Math.round(y)))}for(let i=0;i<=4;i++){const x=range*i/4;node('text',{x:sx(x),y:height-13,fill:'#d8e1ec','font-size':12,'text-anchor':'middle'},money(Math.round(x)))}node('line',{x1:left,y1:sy(plan.target),x2:width-right,y2:sy(plan.target),stroke:'#e9d77c','stroke-width':2,'stroke-dasharray':'7 5'});node('text',{x:width-right-5,y:Math.max(14,sy(plan.target)-7),fill:'#e9d77c','font-size':12,'text-anchor':'end'},'Target profit');names.forEach((name,i)=>{node('line',{x1:sx(0),y1:sy(bidProfitAt(plan,0,name)),x2:sx(range),y2:sy(bidProfitAt(plan,range,name)),stroke:colors[i],'stroke-width':3});const zero=bidBreakEven(plan,name);if(zero!==null&&zero<=range)node('circle',{cx:sx(zero),cy:sy(0),r:5,fill:colors[i],stroke:'#122030','stroke-width':1.5});node('circle',{cx:sx(bid),cy:sy(bidProfitAt(plan,bid,name)),r:5,fill:colors[i]})});node('line',{x1:sx(bid),y1:top,x2:sx(bid),y2:height-bottom,stroke:'#f0f4f9','stroke-width':1.5,'stroke-dasharray':'4 4'});host.append(svg);const legend=el('div',undefined,'bid-chart-legend');names.forEach((name,i)=>{const item=el('span',name+': '+money(Math.round(bidProfitAt(plan,bid,name)))+' profit • break-even '+money(bidBreakEven(plan,name)),'small');item.style.borderLeft='4px solid '+colors[i];legend.append(item)});host.append(legend);for(const row of rows){if(bid>row.ceiling)warnings.append(el('p','⚠️ '+row.name+': '+money(bid)+' exceeds your '+money(row.ceiling)+' target-profit bid ceiling.','watchlist-alert'))}if(!warnings.childNodes.length)warnings.append(el('p','✓ Preview bid stays within all three target-profit ceilings under these assumptions.','small'));$('bid-preview-value').textContent=money(bid)}
function updateBidPlan(){if(!activeBidVehicle)return;const plan={};for(const key of ['target','premium','tax','transport','repairs','other','resale']){const raw=$('bid-'+key).value;plan[key]=raw===''?NaN:Number(raw)}const rows=bidPlanScenarios(activeBidVehicle,plan),out=$('bid-results');out.replaceChildren();if(!rows||rows.some(x=>x.ceiling===null)){out.append(el('p','Enter nonnegative numbers and valid fee percentages to calculate bid ceilings.','small'));return null}for(const row of rows){const cell=el('div',undefined,'profit-scenario');cell.append(el('span',row.name,'small'),el('strong',money(row.ceiling)));out.append(cell)}renderBidChart(plan,rows);const confidence=comparableSales(activeBidVehicle).confidence;$('bid-explanation').textContent='Target profit: '+money(plan.target)+' • Sold-comparison confidence: '+confidence+' • Fee and tax percentages apply to your winning bid. Ceilings are mathematical limits based on assumptions, not verified safe bids. Check final fees, title, condition and shipping before bidding.';return plan}
function saveBidPlan(e){e.preventDefault();const plan=updateBidPlan();if(!plan||!activeBidVehicle)return;const all=readBidPlans();all[activeBidVehicle.id]=plan;localStorage.setItem(BID_PLAN_KEY,JSON.stringify(all));$('bid-dialog').close();render()}
function bidButton(x){const button=el('button','🎯 Max bid','button secondary');button.type='button';button.addEventListener('click',()=>showBidPlan(x));return button}
function profitRiskScore(x,now=Date.now()){const sc=profitScenarios(x),fresh=auctionFreshness(x,now),comp=comparableSales(x),plan=bidPlanDefaults(x);const factors=[];let score=0;const bid=Number(x.price);let headroom=0;if(sc&&plan&&Number.isFinite(bid)&&bid>=0){const expected=bidPlanScenarios(x,plan).find(r=>r.name==='Expected').ceiling;const ratio=expected>0?(expected-bid)/expected:-1;headroom=ratio>=.5?35:ratio>=.25?28:ratio>=.1?20:ratio>=0?10:0}else headroom=0;factors.push({name:'Bid-ceiling headroom',score:headroom,max:35,detail:sc&&plan&&Number.isFinite(bid)?'Reported bid vs expected target-profit ceiling':'No reliable bid or sold-price estimate'});score+=headroom;const evidence=comp.confidence==='moderate'?25:comp.confidence==='limited'?16:comp.confidence==='low'?8:0;factors.push({name:'Completed-sale evidence',score:evidence,max:25,detail:comp.matches.length+' matching completed sales • '+comp.confidence+' confidence'});score+=evidence;const condition=sc?.risk==='high'?4:12;factors.push({name:'Vehicle condition',score:condition,max:20,detail:sc?.risk==='high'?'Title suggests mechanical or condition risk':'Condition not inspected: unknown risk, capped at 12/20'});score+=condition;const freshness=fresh.status==='current'?20:fresh.status==='unverified'?10:fresh.status==='unknown'?3:0;factors.push({name:'Auction freshness',score:freshness,max:20,detail:fresh.label});score+=freshness;return {score,factors,label:score>=75?'Lower modeled risk':score>=50?'Moderate modeled risk':'Higher / unknown risk',headroom,disclaimer:'Heuristic research score, not probability of profit or verified vehicle safety. Third-party GovDeals status remains unverified.'}}
function riskScoreElement(x){const r=profitRiskScore(x),box=el('details',undefined,'risk-score');const summary=el('summary','🛡️ Profit-risk '+r.score+'/100 • '+r.label);box.append(summary);for(const f of r.factors)box.append(el('p',f.name+': '+f.score+'/'+f.max+' • '+f.detail,'small'));box.append(el('p',r.disclaimer,'small muted'));return box}
function dealFilterValues(){const score=Number($('deal-min-score')?.value||0),profit=Number($('deal-min-profit')?.value||0),budget=Number($('deal-max-budget')?.value||0);return {score,profit,budget}}
function dealFilterReason(x,scenario){const f=dealFilterValues(),reasons=[];if(profitRiskScore(x).score<f.score)reasons.push('risk score');if(scenario.scenarios[1].profit<f.profit)reasons.push('expected profit');if(f.budget>0&&(!Number.isFinite(x.price)||x.price>f.budget))reasons.push('reported bid exceeds budget or is unknown');return reasons}
const AUCTION_EVIDENCE_KEY='blakeypoo.auctionEvidence.v1';
function auctionEvidence(){try{return JSON.parse(localStorage.getItem(AUCTION_EVIDENCE_KEY)||'{}')||{}}catch{return {}}}
function evidenceFor(x){return auctionEvidence()[x.id]||{}}
function saveAuctionEvidence(x,form){const url=form.querySelector('[name="source"]')?.value.trim()||'';if(!/^https:\/\/[^\s/]+(?:\/[^\s]*)?$/.test(url))return false;const evidence=auctionEvidence(),fields={};for(const name of ['vin','mileage','condition','description','terms','seller']){const value=form.querySelector('[name="'+name+'"]')?.value.trim();if(value)fields[name]={value:value.slice(0,3000),source_url:url,observed_at:new Date().toISOString(),verification:'user_supplied_unverified'}}evidence[x.id]={fields,source:url,updated_at:new Date().toISOString()};localStorage.setItem(AUCTION_EVIDENCE_KEY,JSON.stringify(evidence));return true}
function nativeEvidenceEditor(x){const form=el('form',undefined,'native-evidence-editor');const heading=el('h3','Add evidence from an authorized source');form.append(heading,el('p','Optional manual research notes. Only enter information you are permitted to use. Saved locally on this device; user-supplied fields are NOT independently verified.','small muted'));const existing=evidenceFor(x),url=el('input');url.name='source';url.type='url';url.required=true;url.placeholder='https://source.example/listing';url.value=existing.source||'';const sourceLabel=el('label','Source URL');sourceLabel.append(url);form.append(sourceLabel);for(const [key,label] of [['vin','VIN'],['mileage','Mileage'],['condition','Condition'],['description','Description'],['seller','Seller'],['terms','Auction terms']]){const field=key==='description'||key==='terms'?el('textarea'):el('input');field.name=key;field.value=existing.fields?.[key]?.value||'';field.maxLength=3000;const labelNode=el('label',label);labelNode.append(field);form.append(labelNode)}const button=el('button','Save sourced notes','button');button.type='submit';form.append(button);form.addEventListener('submit',e=>{e.preventDefault();if(saveAuctionEvidence(x,form))showNativeAuction(x)});return form}
function nativeDetailFields(x){const notes=evidenceFor(x).fields||{};const valueOf=k=>x.details?.[k]||notes[k];const values=[['Description',valueOf('description')],['VIN',valueOf('vin')],['Mileage',valueOf('mileage')],['Condition',valueOf('condition')],['Seller',valueOf('seller')],['County',x.details?.county],['Category',x.details?.category],['Closing time',x.details?.closing_text],['First observed by source',x.details?.first_seen],['Auction terms',valueOf('terms')]];const section=el('section',undefined,'native-auction-fields');section.append(el('h3','Source-backed listing fields'));for(const [label,entry] of values){const line=el('div',undefined,'native-auction-field');line.append(el('strong',label),el('span',entry?.value||'Not available from current source'));if(entry?.source_url){const a=el('a','Source ↗','small');a.href=entry.source_url;a.target='_blank';a.rel='noopener noreferrer';line.append(a,el('small','Observed: '+(entry.observed_at||'Unknown')+' • '+(entry.verification||'Unverified'),'muted'))}section.append(line)}return section}
function workspaceSection(title){const section=el('section',undefined,'workspace-section');section.append(el('h3',title));return section}
function workspaceComps(x){const section=workspaceSection('📊 Completed-sale comparisons'),comps=matchingSold(x),quality=comparableSales(x);section.append(el('p',comps.length+' matching completed auction sales • '+quality.confidence+' confidence'+(comps.length?' • Median '+money(median(comps.map(c=>c.price))):' • No verified match'),'small'));for(const c of comps.slice(0,8)){const a=el('a',c.title+' • '+c.sold_date+' • '+money(c.price)+' ↗','workspace-comp');a.href=c.url;a.target='_blank';a.rel='noopener noreferrer';section.append(a)}if(!comps.length)section.append(el('p','No matching completed sales available. Do not assume a resale price.','small muted'));section.append(el('p','These are completed auction prices, not guaranteed retail resale values. Mileage, trim and condition may differ.','small muted'));return section}
function workspaceProfit(x){const section=workspaceSection('💰 Profit scenarios'),scenario=profitScenarios(x);if(!scenario){section.append(el('p','No supported profit estimate. Add verified resale assumptions before calculating a margin.','small muted'));return section}const rows=el('div',undefined,'profit-scenarios');for(const v of scenario.scenarios){const c=el('div',undefined,'profit-scenario');c.append(el('span',v.name,'small'),el('strong',money(v.profit)));rows.append(c)}section.append(rows,el('p','Expected scenario includes estimated premium '+scenario.feeRate+'%, transport '+money(scenario.transport)+', illustrative 7% tax and condition reserve. Not a guarantee.','small muted'));const edit=el('button','Edit costs and compare sales','button secondary');edit.type='button';edit.addEventListener('click',()=>{ $('auction-detail-dialog').close();openResale(x)});section.append(edit);return section}
function workspaceCeilings(x){const section=workspaceSection('🎯 Maximum bid ceilings'),plan=bidPlanDefaults(x);if(!plan){section.append(el('p','Bid ceilings unavailable without a resale estimate.','small muted'));return section}section.append(el('p','Target profit '+money(plan.target)+' • Resale assumption '+money(plan.resale),'small'));const rows=el('div',undefined,'profit-scenarios');for(const r of bidPlanScenarios(x,plan)){const c=el('div',undefined,'profit-scenario');c.append(el('span',r.name,'small'),el('strong',r.ceiling===null?'Unavailable':money(r.ceiling)));rows.append(c)}section.append(rows);const button=bidButton(x);button.addEventListener('click',()=>$('auction-detail-dialog').close());section.append(button,el('p','Ceilings depend on editable assumptions and do not represent verified safe bids.','small muted'));return section}
function workspaceNotes(x){const section=workspaceSection('📝 Saved research notes');if(x.source?.startsWith('GovDeals'))section.append(nativeEvidenceEditor(x));else section.append(el('p','Additional sourced notes are currently supported for GovDeals vehicles.','small muted'));return section}
function showNativeAuction(x){const dialog=$('auction-detail-dialog'),body=$('auction-detail-body');body.replaceChildren();body.append(el('h2',x.title),el('p',x.source+' • '+(x.city||'Location unknown')+', '+(x.state||''),'small'));if(x.image&&(/^\.\/auction-images\/[a-f0-9]{20}\.jpg$/.test(x.image)||/^https:\/\/(?:webassets\.lqdt1\.com\/assets\/photos\/|files\.lqdt1\.com\/photos\/)/.test(x.image))){const img=document.createElement('img');img.src=x.image;img.alt=x.title;img.className='watchlist-photo';img.loading='lazy';body.append(img)}body.append(el('p','Reported bid: '+(Number.isFinite(x.price)?money(x.price):'Unknown')+' • Reported closing: '+(x.ends||'Unknown'),'small'),el('p','Listing source: '+x.source+' • Source observation: '+(x.observed_at||feedHealth.gsa?.fetched_at||'Unknown')+' • Official live status: '+(x.source?.startsWith('GovDeals')?'not independently verified':'GSA feed snapshot'),'small muted'),el('p',auctionFreshness(x).label,'watchlist-alert'));body.append(nativeDetailFields(x),workspaceComps(x),workspaceProfit(x),workspaceCeilings(x),riskScoreElement(x),workspaceNotes(x));if(x.description)body.append(el('p',x.description,'small'));if(x.source_page)body.append(el('p','Third-party source page: '+x.source_page,'small muted'));body.append(el('p','Native BlakeyPoo listing summary assembled from available source data, not a live copy of GovDeals. Confirm price, title, condition and bidding terms at the official auction.','small muted'));const link=el('a','Verify at official auction ↗','button');link.href=x.url;link.target='_blank';link.rel='noopener noreferrer';body.append(link);dialog.showModal()}
