function renderTopDeals(){const target=$('top-deals-list');if(!target)return;target.replaceChildren();const eligible=[...govVehicles,...liveVehicles].map(x=>({x,scenario:profitScenarios(x),fresh:auctionFreshness(x)})).filter(v=>v.scenario&&!['ended','stale'].includes(v.fresh.status));const excluded={};const ranked=eligible.filter(v=>{const reasons=dealFilterReason(v.x,v.scenario);for(const reason of reasons)excluded[reason]=(excluded[reason]||0)+1;return !reasons.length}).sort((a,b)=>{const conf=c=>c==='moderate'?3:c==='limited'?2:c==='low'?1:0;return conf(b.scenario.confidence)-conf(a.scenario.confidence)||b.scenario.scenarios[1].profit-a.scenario.scenarios[1].profit||(Number.isFinite(endingTime(a.x))?endingTime(a.x):1e15)-(Number.isFinite(endingTime(b.x))?endingTime(b.x):1e15)}).slice(0,12);$('top-deals-count').textContent=ranked.length+' displayed (up to 12) of '+eligible.length+' eligible • Filtered out: '+Object.entries(excluded).map(([k,v])=>k+' '+v).join(', ')+' • Scenarios are illustrative';if(!ranked.length){target.append(el('p','No evidence-backed opportunities available in the current feeds.','muted'));return}for(const {x,scenario,fresh} of ranked){const card=el('article',undefined,'top-deal-card');card.append(el('h3',x.title),el('p','Sold comparisons: '+scenario.comps+' • '+scenario.confidence+' confidence • Condition risk: '+scenario.risk,'small'),el('p','Bid: '+money(x.price)+' • Ends: '+(x.ends||'Unknown')+' • '+x.source,'small'),el('p',fresh.label,'small muted'));const scenarios=el('div',undefined,'profit-scenarios');for(const row of scenario.scenarios){const cell=el('div',undefined,'profit-scenario');cell.append(el('span',row.name,'small'),el('strong',money(row.profit)));scenarios.append(cell)}card.append(scenarios,riskScoreElement(x),el('p','Assumed premium: '+scenario.feeRate+'%'+(scenario.feeVerified?' (user-entered)':' (unverified)')+' • Purchase tax: 7% illustrative • Expected repair reserve: '+money(scenario.scenarios[1].repairs)+' • Transport: '+money(scenario.scenarios[1].shipping),'small muted'));const actions=el('div',undefined,'watchlist-actions'),link=el('a','View auction ↗','button');link.href=x.url;link.target='_blank';link.rel='noopener noreferrer';const save=el('button',isVehicleSaved(x)?'✓ Saved':'📌 Save','button secondary');save.disabled=isVehicleSaved(x);save.addEventListener('click',()=>{if(saveVehicle(x)){save.disabled=true;save.textContent='✓ Saved'}});const details=el('button','Edit costs / see comps','button secondary');details.addEventListener('click',()=>openResale(x));actions.append(auctionDetailButton(x),link,save,details,bidButton(x));card.append(actions);target.append(card)}}
function renderVehicles(){const radius=$('vehicle-radius').value,items=nearbyVehicles(),target=$('vehicle-carousel');target.replaceChildren();vehicleIndex=Math.min(vehicleIndex,Math.max(0,items.length-1));$('vehicle-location-status').textContent=feedStatus+(radius==='all'?' • Nationwide':viewerLocation?' • Within '+radius+' miles':' • Select Set my location to filter within '+radius+' miles');if(radius!=='all'&&!viewerLocation){target.append(el('div','📍 Tap “Set my location” to filter listings within '+radius+' miles. Or choose Anywhere to see all national auctions.','vehicle-slide'))}else if(!items.length){target.append(el('div','No matching GSA passenger vehicle auctions in this area in the latest feed. Choose Anywhere or try a larger radius.','vehicle-slide'))}else for(const x of items){const slide=el('article',undefined,'vehicle-slide');if(x.image&&(/^\.\/auction-images\/[a-f0-9]{20}\.jpg$/.test(x.image)||/^https:\/\/(?:webassets\.lqdt1\.com\/assets\/photos\/|files\.lqdt1\.com\/photos\/)/.test(x.image))){const photo=document.createElement('img');photo.src=x.image;photo.alt='Auction photo for '+x.title;photo.loading='lazy';photo.className='vehicle-photo';photo.referrerPolicy='no-referrer';slide.append(photo)}const locationText=viewerLocation&&Number.isFinite(x.lat)&&Number.isFinite(x.lon)?' • '+Math.round(distanceMiles(viewerLocation.lat,viewerLocation.lon,x.lat,x.lon))+' mi approx.':'';slide.append(el('span',x.source+locationText,'pill'),el('h3',x.title),el('div',x.price===null?'Bid not reported':money(x.price),'vehicle-price'),el('p','Current reported high bid • Not final sale price','small muted'),el('p',x.city+', '+x.state,'small'),el('p','Auction ends: '+(x.ends||'See listing'),'small'));const freshness=auctionFreshness(x);slide.append(el('p',freshness.label,freshness.status==='current'?'small muted':'watchlist-alert'));const a=el('a','View live auction ↗','button');a.href=x.url;a.target='_blank';a.rel='noopener noreferrer';slide.append(auctionDetailButton(x),a);const saveButton=el('button',isVehicleSaved(x)?'✓ Saved to BlakeyPoo':'📌 Save to BlakeyPoo','button secondary vehicle-save');saveButton.type='button';saveButton.disabled=isVehicleSaved(x);saveButton.addEventListener('click',()=>{if(saveVehicle(x)){saveButton.textContent='✓ Saved to BlakeyPoo';saveButton.disabled=true}else saveButton.textContent='Unable to save • check browser storage'});slide.append(saveButton);const scenario=profitScenarios(x);if(scenario)slide.append(el('p','Profit scenarios: '+scenario.scenarios.map(r=>r.name+' '+money(r.profit)).join(' • '),'small'));const estimate=getResale(x.id),isAuto=!!estimate&&!resaleCalc(readResale()[x.id]),star=el('button',estimate?'★ '+money(estimate.profit)+(isAuto?' est.':''):'★ No comp','resale-star');star.type='button';star.setAttribute('aria-label','Resale Analysis for '+x.title+(estimate?', estimated profit '+money(estimate.profit):', estimate not set'));star.addEventListener('click',()=>openResale(x));slide.append(star);target.append(slide)}$('vehicle-page').textContent=items.length?(vehicleIndex+1)+' / '+items.length:'0 vehicles';$('vehicle-prev').disabled=vehicleIndex===0;$('vehicle-next').disabled=vehicleIndex>=items.length-1;if(items.length)target.children[vehicleIndex].scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'})}
function shiftVehicle(delta){const items=nearbyVehicles();vehicleIndex=Math.max(0,Math.min(items.length-1,vehicleIndex+delta));renderVehicles()}
function requestVehicleLocation(){if(!navigator.geolocation){$('vehicle-location-status').textContent='Location unavailable in this browser.';return}$('vehicle-location-status').textContent='Requesting location permission…';navigator.geolocation.getCurrentPosition(pos=>{viewerLocation={lat:pos.coords.latitude,lon:pos.coords.longitude};vehicleIndex=0;renderVehicles()},err=>{$('vehicle-location-status').textContent='Location unavailable ('+(err.code===1?'permission denied':'unable to determine position')+'). Allow location access in Safari settings and try again.'},{enableHighAccuracy:false,timeout:12000,maximumAge:300000})}
function init(){showStartupSplash();migrate();loadAnalysisSources().then(()=>{watchdogAnalysisReady=true;render();renderFeedHealth();renderTopDeals();captureWatchdog()});$('resale-destination').addEventListener('input',()=>{if(activeResale)populateAutomaticResale(activeResale,readResale()[activeResale.id]||{})});$('resale-form').addEventListener('submit',saveResale);$('watchdog-alert-enable').addEventListener('click',enableWatchdogAlerts);$('watchdog-personalized').addEventListener('change',e=>{const settings=alertSettings();settings.personalized=e.target.checked;saveAlertSettings(settings);renderWatchdog()});renderAlertSettings();$('watchdog-clear').addEventListener('click',()=>{localStorage.removeItem(WATCHDOG_KEY);renderWatchdog()});$('comparison-clear').addEventListener('click',()=>{setComparisonSelection([]);render()});$('auction-detail-close').addEventListener('click',()=>$('auction-detail-dialog').close());for(const id of ['deal-min-score','deal-min-profit','deal-max-budget'])$(id).addEventListener('input',renderTopDeals);$('bid-form').addEventListener('submit',saveBidPlan);$('bid-preview').addEventListener('input',updateBidPlan);$('bid-close').addEventListener('click',()=>$('bid-dialog').close());for(const key of ['target','premium','tax','transport','repairs','other','resale'])$('bid-'+key).addEventListener('input',updateBidPlan);$('resale-close').addEventListener('click',()=>$('resale-dialog').close());$('resale-clear').addEventListener('click',()=>{if(!activeResale)return;const all=readResale();delete all[activeResale.id];localStorage.setItem(RESALE_KEY,JSON.stringify(all));$('resale-dialog').close();renderVehicles();renderTopDeals()});for(const id of ['resale-cost','resale-shipping','resale-premium','resale-other','resale-value'])$(id).addEventListener('input',updateResaleBreakdown);const frame=$('govdeals-frame');const reloadBrowser=()=>{showLoading('Connecting to GovDeals…');$('browser-status').textContent='Attempting to load official GovDeals. If blank, use Open official GovDeals.';frame.src='https://www.govdeals.com/';requestAnimationFrame(()=>requestAnimationFrame(hideLoading))};$('browser-reload').addEventListener('click',reloadBrowser);frame.addEventListener('load',()=>{$('browser-status').textContent='The embedded website responded. If blank or blocked, tap Open official GovDeals.'});document.querySelectorAll('[data-nav="browser"]').forEach(b=>b.addEventListener('click',()=>{if(!frame.getAttribute('src'))reloadBrowser()}));loadLiveVehicles();$('locate-vehicles').addEventListener('click',requestVehicleLocation);$('vehicle-radius').addEventListener('change',()=>{vehicleIndex=0;renderVehicles()});$('vehicle-sort').addEventListener('change',()=>{vehicleIndex=0;renderVehicles()});$('vehicle-prev').addEventListener('click',()=>shiftVehicle(-1));$('vehicle-next').addEventListener('click',()=>shiftVehicle(1));$('vehicle-carousel').addEventListener('scroll',()=>{const cards=[...$('vehicle-carousel').children];if(!cards.length||!nearbyVehicles().length)return;let closest=0,dist=Infinity;cards.forEach((card,i)=>{const d=Math.abs(card.offsetLeft-$('vehicle-carousel').scrollLeft);if(d<dist){dist=d;closest=i}});vehicleIndex=closest;$('vehicle-page').textContent=(vehicleIndex+1)+' / '+cards.length;$('vehicle-prev').disabled=vehicleIndex===0;$('vehicle-next').disabled=vehicleIndex===cards.length-1});document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.nav)));$('listing-form').addEventListener('submit',submit);$('auction').addEventListener('input',()=>{$('auction').setCustomValidity('');$('feedback').textContent=''});for(const id of ['bid','fees','resale'])$(id).addEventListener('input',updateEstimate);for(const id of ['filter-text','filter-category','filter-status','sort'])$(id).addEventListener('input',render);$('copy-link').addEventListener('click',async()=>{$('copy-link').textContent=await copy(location.href)?'Copied!':'Copy unavailable'});$('share').addEventListener('click',async()=>{if(navigator.share){try{await navigator.share({title:'BlakeyPoo',url:location.href})}catch{}}else $('copy-link').click()});const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true,ios=/iPad|iPhone|iPod/.test(navigator.userAgent);if(ios&&!standalone&&!sessionStorage.getItem('blakeypoo.install.dismissed'))$('install-hint').classList.remove('hidden');$('dismiss-hint').addEventListener('click',()=>{sessionStorage.setItem('blakeypoo.install.dismissed','1');$('install-hint').classList.add('hidden')});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});render()}
init();window.addEventListener('pageshow',e=>{if(e.persisted)showStartupSplash()});let lastHiddenAt=0;document.addEventListener('visibilitychange',()=>{if(document.hidden){lastHiddenAt=Date.now()}else if(lastHiddenAt&&Date.now()-lastHiddenAt>3000){showStartupSplash();lastHiddenAt=0}});
